// Mete complete della prima ondata: Europa e Mediterraneo (ottobre 2026).
// Sostituiscono le stime generiche delle città già presenti (stesso id) e aggiungono mete nuove.
// M(id, nome, paese, aeroporto, lat, lon,
//   [ostello a persona, hotel a camera, appartamento, cibo al giorno, trasporti al giorno, attività al giorno],
//   tag, nota, "luogo|costo;..." (6 luoghi), "serata|costo;..." (3 serate), gita, extra)
// extra: 1 = si arriva solo in aereo (isole, oltre il mare); "med" = fuori Europa ma a corto raggio, solo in aereo.
// I costi sono in euro, a stagione media: il calcolo applica poi la stagione delle date scelte.
const M = (id, name, cc, iata, lat, lon, k, tags, note, day, eve, gita, x) => ({ id, name, cc, iata, lat, lon, k, tags, note, day, eve, gita, x });

